// var 示例
var name = '小明';
function test() {
  if (true) {
    var age = 18; // 函数作用域，外部可访问
  }
  console.log(age); // 18
}

// let 示例
let city = '北京';
{
  let area = '朝阳';
  console.log(area); // 朝阳
}
// console.log(area); // 报错：area未定义

// const 示例
const PI = 3.14;
// PI = 3.1415; // 报错：给常量赋值
const obj = { key: 'value' };
obj.key = 'new'; // 允许，因为对象内容未改变引用
